import {editableTarget} from './selection.js';
export function installShortcuts(E,commands){window.addEventListener('keydown',e=>{const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase(),editing=editableTarget(e.target);if(mod&&key==='s'){e.preventDefault();E.save();return;}if(editing||document.querySelector('#modal').open)return;if(E.mode!=='edit'&&!['0','1','escape'].includes(key))return;if(mod&&key==='y'){e.preventDefault();E.redo();return;}if(mod&&['c','x','v','a'].includes(key)){e.preventDefault();if(key==='a'){E.selection.clear();E.doc.blocks.filter(b=>b.visible&&!b.locked).forEach(b=>E.selection.add(b.id));E.setSelected([...E.selection].at(-1));E.draw();E.inspector();}else commands({c:'copy',x:'cut',v:'paste'}[key]);return;}if(e.key==='Escape'){commands('restore-isolation');}if(mod&&key==='0'){e.preventDefault();E.fit();}if(mod&&key==='1'){e.preventDefault();E.zoom(1);}},true);}
